CREATE TABLE ibexa_content_trash (node_id INT DEFAULT 0 NOT NULL, contentobject_id INT DEFAULT NULL, contentobject_version INT DEFAULT NULL, depth INT DEFAULT 0 NOT NULL, is_hidden INT DEFAULT 0 NOT NULL, is_invisible INT DEFAULT 0 NOT NULL, main_node_id INT DEFAULT NULL, modified_subnode INT DEFAULT 0, parent_node_id INT DEFAULT 0 NOT NULL, path_identification_string LONGTEXT DEFAULT NULL, path_string VARCHAR(255) DEFAULT '' NOT NULL, priority INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT '' NOT NULL, sort_field INT DEFAULT 1, sort_order INT DEFAULT 1, trashed INT DEFAULT 0 NOT NULL, INDEX ibexa_content_trash_depth (depth), INDEX ibexa_content_trash_p_node_id (parent_node_id), INDEX ibexa_content_trash_path_ident (path_identification_string(50)), INDEX ibexa_content_trash_co_id (contentobject_id), INDEX ibexa_content_trash_modified_subnode (modified_subnode), INDEX ibexa_content_trash_path (path_string(191)), PRIMARY KEY(node_id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
